export const layouts = [
 ['plain',s=>s],
 ['bullets',s=>`Professional experience\n• ${s}\n• Maintained meeting calendars.`],
 ['crlf',s=>`Professional experience\r\n${s}\r\nMaintained meeting calendars.`],
];
export const volumeCases=actions.flatMap(([occupation,requirement,past,base],i)=>contexts.flatMap(([context,supported,render])=>layouts.map(([layout,wrap])=>({
 id:`volume-${i}-${context}-${layout}`,occupation,context,layout,requirement,
 resume:wrap(render(past,base)),expected:supported?'supported':'not_supported',
}))));
